import React, { Fragment } from "react"
import  {Spinner}  from "./Spinner"

const ShowSpinner = props => {
  const { position } = props

  return (
    <Fragment>
      {position === 1 ? <Spinner area="getUserProfile" spinnerMessage="Loading your profile, please wait... " /> : null}
      {position === 2 ? (
        <div>
          <Spinner area="dummy" spinnerMessage="Preparing the summary, please wait... " />   
        </div>
      ) : null}
      {position === 3 ? (
        <div>         
          <Spinner area="typeOfLeave" spinnerMessage="Validating the input, please wait... " />  
          <Spinner area="printSummary" spinnerMessage="Generating the Leave Summary, please wait... " />   
          <Spinner area="getRefDetails" spinnerMessage="Reloading the leave details, please wait... " /> 
        </div>
      ) : null}
      
      {position === 4 ? (
        <div>               
          <Spinner area="switchUser" spinnerMessage="Switching the user, please wait... " /> 
          <Spinner area="approvalCenter" spinnerMessage="Loading approval details, please wait... " /> 
          <Spinner area="cancelLeave" spinnerMessage="Loading applied leave details, please wait... " /> 
          <Spinner area="changeStatus" spinnerMessage="Updating status, please wait... " /> 
          <Spinner area="getSharePoint" spinnerMessage="Getting SharePoint list, please wait... " /> 
          <Spinner area="deleteSharePoint" spinnerMessage="Deleting SharePoint files, please wait... " /> 
          <Spinner area="uploadSharePoint" spinnerMessage="Uploading SharePoint files, please wait... " /> 
          <Spinner area="downloadSharePoint" spinnerMessage="Downloading SharePoint files, please wait... " /> 
          <Spinner area="partnersLeave" spinnerMessage="Loading partners leave details, please wait... " /> 
          <Spinner area="otherLeave" spinnerMessage="Submitting requisition, please wait... " /> 
          <Spinner area="cancelOtherLeave" spinnerMessage="Cancelling requisition, please wait... " /> 
          <Spinner area="getNewRefno" spinnerMessage="Assigning approval number, please wait... " /> 
          <Spinner area="getRefListinCancel" spinnerMessage="Searching reference list for applicant, please wait... " /> 
          <Spinner area="getRefDetails" spinnerMessage="Reloading the leave details, please wait... " /> 
          <Spinner area="getRefList" spinnerMessage="Searching reference list for applicant, please wait... " /> 
        </div>
      ) : null}
      
    </Fragment>
  )
}
export default ShowSpinner
